UPDATE public.hostings SET candle_lighting_at='2026-11-20T14:20:00Z',feedback_opens_at='2026-11-21T15:16:21Z' WHERE id='a4500000-0000-4000-8000-000000000010';
UPDATE public.feedback SET answers=jsonb_build_object('overall','נחמד'),free_text='נחמד, אבל אעדיף פעם אחרת סגנון אחר – משוב פיקטיבי.' WHERE hosting_id='a4500000-0000-4000-8000-000000000007' AND author_role='guest';
DO $tests$ DECLARE w jsonb; ops jsonb; BEGIN
IF (SELECT count(*) FROM public.demo_participants)<>18 THEN RAISE EXCEPTION 'expected 18 story participants'; END IF;
IF (SELECT count(*) FROM public.host_profiles h JOIN public.demo_participants d ON d.person_id=h.person_id WHERE h.approval='approved')<>8 THEN RAISE EXCEPTION 'expected 8 approved families'; END IF;
IF (SELECT count(*) FROM public.guest_profiles g JOIN public.demo_participants d ON d.person_id=g.person_id)<>8 THEN RAISE EXCEPTION 'expected 8 guests'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.hostings WHERE guest_id='809f85d8-4640-4860-badc-45cba7b5fb4a' AND host_id='ed5895e3-934e-4220-91a1-f70cc937103c' AND status='confirmed' AND shabbat_date='2026-11-21') THEN RAISE EXCEPTION 'demo pair must be confirmed this Shabbat'; END IF;
IF (SELECT count(*) FROM public.hostings WHERE id::text LIKE 'a450%' AND status='confirmed')<>3 THEN RAISE EXCEPTION 'expected 3 confirmed visits'; END IF;
IF (SELECT count(*) FROM public.hostings WHERE id::text LIKE 'a450%' AND status='took_place')<>6 THEN RAISE EXCEPTION 'expected 6 past visits'; END IF;
IF (SELECT count(*) FROM public.feedback WHERE hosting_id::text LIKE 'a450%')<>12 THEN RAISE EXCEPTION 'each past visit needs both feedbacks'; END IF;
IF (SELECT count(*) FROM public.responses WHERE id::text LIKE 'a470%' AND status='pending')<>3 THEN RAISE EXCEPTION 'expected 3 pending responses'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.identity_checks WHERE person_id='a4000000-0000-4000-8000-000000000009' AND attempts=3 AND status='manual_review') THEN RAISE EXCEPTION 'manual review fixture missing'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.persons WHERE id='a4000000-0000-4000-8000-000000000005' AND restriction_status='frozen') THEN RAISE EXCEPTION 'reported host must be frozen'; END IF;
IF EXISTS(SELECT 1 FROM public.notifications WHERE id::text LIKE 'a490%' AND provider<>'mock') THEN RAISE EXCEPTION 'only mock messages allowed'; END IF;
w:=public.staff_workspace('2f79a37c-468f-4bf5-90c4-c0adef2190cc');
IF jsonb_array_length(w->'people')<>18 THEN RAISE EXCEPTION 'demo staff must see all 18 participants'; END IF;
ops:=public.staff_operations('2f79a37c-468f-4bf5-90c4-c0adef2190cc');
IF jsonb_array_length(ops->'hostings')<10 THEN RAISE EXCEPTION 'demo staff hosting projection missing story'; END IF;
IF (SELECT count(*) FROM public.availability WHERE host_id IN(SELECT person_id FROM public.demo_participants) AND shabbat_date BETWEEN '2026-11-21' AND '2026-12-26')<48 THEN RAISE EXCEPTION 'expected six weeks of invitations'; END IF;
IF has_table_privilege('authenticated','public.demo_participants','SELECT') THEN RAISE EXCEPTION 'registry must remain private'; END IF;
END $tests$;